def recovered_makefile(before):
    if sha(before.encode())!=MAKE_BEFORE_SHA:raise ValueError('Inherited Makefile changed')
    return MAKE_AFTER
def check_pool(obj):
    pools=normalized_pools(obj)
    if pools!={'.data':None,'.rodata':(bytes.fromhex('4520a0004570a0000000000000000000'),())}:raise ValueError('Distance fade retail literal pool changed')
    return pools
